    {"slug": "java-streams", "track": "java", "title": "Streams Intro", "minutes": 18, "level": "Intermediate",
     "summary": "Filter, map, and reduce collections with the Stream API.",
     "objectives": ["Create a stream from a List", "Use filter/map/collect", "Run a simple reduction", "Know streams are not reusable"],
     "sections": [
         ("code", "java", 'import java.util.*;\nimport java.util.stream.Collectors;\n\npublic class StreamDemo {\n    public static void main(String[] args) {\n        List<Integer> nums = List.of(1, 2, 3, 4, 5, 6);\n        List<Integer> evensSquared = nums.stream()\n            .filter(n -> n % 2 == 0)\n            .map(n -> n * n)\n            .collect(Collectors.toList());\n        System.out.println(evensSquared);\n\n        int sum = nums.stream().mapToInt(Integer::intValue).sum();\n        System.out.println(sum);\n    }\n}'),
         ("p", "Streams shine for declarative data pipelines. For simple loops, a classic for-each is still fine."),
         ("exercise", "From a list of words, collect uppercase words longer than 3 characters into a new list."),
     ]},
    {"slug": "java-mini-project", "track": "java", "title": "Mini Project: Student Registry", "minutes": 25, "level": "Intermediate",
     "summary": "Build an in-memory student registry using classes, ArrayList, and a simple menu.",
     "objectives": ["Model a Student class", "Store students in a List", "Search by id", "Print a formatted roster"],
     "sections": [
         ("p", "Combine OOP and collections into a tiny app you can extend later with file persistence."),
         ("h2", "Starter"),
         ("code", "java", 'import java.util.*;\n\nclass Student {\n    final String id;\n    final String name;\n    final double gpa;\n\n    Student(String id, String name, double gpa) {\n        this.id = id;\n        this.name = name;\n        this.gpa = gpa;\n    }\n\n    public String toString() {\n        return id + " | " + name + " | " + gpa;\n    }\n}\n\npublic class Registry {\n    private final List<Student> students = new ArrayList<>();\n\n    void add(Student s) { students.add(s); }\n\n    Student find(String id) {\n        for (Student s : students) {\n            if (s.id.equals(id)) return s;\n        }\n        return null;\n    }\n\n    void printAll() {\n        for (Student s : students) System.out.println(s);\n    }\n\n    public static void main(String[] args) {\n        Registry r = new Registry();\n        r.add(new Student("s1", "Ada", 3.9));\n        r.add(new Student("s2", "Linus", 3.5));\n        r.printAll();\n        System.out.println(r.find("s1"));\n    }\n}'),
         ("exercise", "Add <code>remove(String id)</code> and <code>averageGpa()</code>. Reject duplicate IDs on add with an exception."),
     ]},
